import com.project.system.service.WalletService;import java.math.BigDecimal;import java.util.*;import org.springframework.context.annotation.AnnotationConfigApplicationContext;import org.springframework.jdbc.core.JdbcTemplate;
public class WalletLossIntegration{public static void main(String[]args){try(AnnotationConfigApplicationContext c=new AnnotationConfigApplicationContext(WalletIdentityIntegration.Config.class)){WalletService s=c.getBean(WalletService.class);JdbcTemplate db=c.getBean(JdbcTemplate.class);s.status(2,"LOST");if(!"LOST".equals(s.info(2).get("status")))throw new AssertionError();System.out.println("PASS wallet becomes lost");BigDecimal before=(BigDecimal)s.info(2).get("balance");int count=db.queryForObject("select count(*) from campus_ledger where user_id=2",Integer.class);try{s.trade(2,"PAY",new BigDecimal("0.01"),3L,null,UUID.randomUUID().toString(),1);throw new AssertionError();}catch(IllegalArgumentException e){System.out.println("PASS lost wallet rejects debit");}if(db.queryForObject("select count(*) from campus_ledger where user_id=2",Integer.class)!=count||((BigDecimal)s.info(2).get("balance")).compareTo(before)!=0)throw new AssertionError();System.out.println("PASS rejected debit preserves balance and ledger");String key=UUID.randomUUID().toString();long id=s.trade(2,"RECHARGE",BigDecimal.ONE,null,null,key,1);if(s.trade(2,"RECHARGE",BigDecimal.ONE,null,null,key,1)!=id||((BigDecimal)s.info(2).get("balance")).compareTo(before.add(BigDecimal.ONE))!=0||!"LOST".equals(s.info(2).get("status")))throw new AssertionError();System.out.println("PASS lost wallet accepts recharge once and remains lost");s.status(2,"ACTIVE");s.trade(2,"PAY",new BigDecimal("0.01"),3L,null,UUID.randomUUID().toString(),1);System.out.println("PASS restored wallet accepts debit");}}}
